-- VEGANFARM phase 3. Run AFTER supabase-setup.sql and supabase-phase2.sql. Safe to re-run. Deletes no data.

-- Case code VF-0001, VF-0002 ... generated by the database
create sequence if not exists case_code_seq start 1;
alter table rescue_cases add column if not exists kind text default 'Treatment',
  add column if not exists urgent boolean not null default false,
  add column if not exists review_note text,
  add column if not exists extra jsonb not null default '{}';
alter table rescue_cases alter column case_code set default ('VF-'||lpad(nextval('case_code_seq')::text,4,'0'));

-- Expense fields the dashboard uses
alter table expenses add column if not exists category text, add column if not exists project text, add column if not exists expense_date date;

-- Private finder contact details: only the Founder can read them
create table if not exists public.case_private (
  case_id uuid primary key references rescue_cases(id) on delete cascade,
  finder_name text, finder_phone text, created_at timestamptz not null default now());
alter table case_private enable row level security;
drop policy if exists cp_f on case_private; create policy cp_f on case_private for all using (is_founder()) with check (is_founder());
drop policy if exists cp_i on case_private; create policy cp_i on case_private for insert to authenticated with check (is_team());
revoke all on case_private from anon;
drop trigger if exists audit_case_private on case_private;
create trigger audit_case_private after insert or update or delete on case_private for each row execute function audit_row();

-- Financial integrity: approved expenses cannot exceed the balance; settled money is corrected by reversal, never edited or deleted.
create or replace function public.guard_money() returns trigger language plpgsql security definer set search_path=public as $$
declare bal numeric;
begin
  if TG_OP='DELETE' then
    if old.status in ('verified','approved','reversed') then raise exception 'Settled records cannot be deleted. Mark them reversed instead.'; end if;
    return old;
  end if;
  if old.status in ('verified','approved','reversed') and new.amount is distinct from old.amount then
    raise exception 'Settled amounts cannot be edited. Reverse the record and enter a new one.'; end if;
  if old.status in ('reversed') and new.status is distinct from old.status then raise exception 'A reversed record is final.'; end if;
  if TG_TABLE_NAME='expenses' and new.status='approved' and old.status is distinct from 'approved' then
    select coalesce((select sum(amount) from donations where status='verified'),0)-coalesce((select sum(amount) from expenses where status='approved'),0) into bal;
    if new.amount>bal then raise exception 'Expense exceeds the available balance'; end if;
  end if;
  return new;
end $$;
drop trigger if exists guard_don on donations; create trigger guard_don before update or delete on donations for each row execute function guard_money();
drop trigger if exists guard_exp on expenses;  create trigger guard_exp before update or delete on expenses  for each row execute function guard_money();

-- Nobody can change their own role or status (stops self-promotion and Founder lock-out)
create or replace function public.guard_profile() returns trigger language plpgsql security definer set search_path=public as $$
begin
  if auth.uid() is not null and old.id=auth.uid() and (new.role is distinct from old.role or new.status is distinct from old.status) then
    raise exception 'You cannot change your own role or status'; end if;
  return new;
end $$;
drop trigger if exists guard_prof on profiles; create trigger guard_prof before update on profiles for each row execute function guard_profile();

-- Team members may edit only their own cases that are still draft/pending (policy already set); make Founder-only fields immutable for them
create or replace function public.guard_case() returns trigger language plpgsql security definer set search_path=public as $$
begin
  if not is_founder() and (new.publication is distinct from old.publication or new.target_amount is distinct from old.target_amount) then
    raise exception 'Only the Founder can publish a case or set its target'; end if;
  return new;
end $$;
drop trigger if exists guard_case_t on rescue_cases; create trigger guard_case_t before update on rescue_cases for each row execute function guard_case();
